def compare(a: int, b: int) -> int:
    if a > b:
        return 1
    elif a < b:
        return -1
    return 0

def sort_desc(arr: list) -> list:
    n = len(arr)
    for i in range(n - 1):
        for j in range(n - 1 - i):
            # 降序：前一个元素小于后一个元素时才交换
            if compare(arr[j], arr[j + 1]) < 0:
                arr[j], arr[j + 1] = arr[j + 1], arr[j]
    return arr

def top_k(arr: list, k: int) -> list:
    if k <= 0:
        return []
    # 先复制，避免原地排序污染调用方列表
    sorted_arr = sort_desc(list(arr))
    if k >= len(sorted_arr):
        return sorted_arr
    return sorted_arr[:k]
# noise_seed=110

