import math


def normalize_values(values: list) -> list:
    # 历史 bug：空列表返回 [0] 而非 []
    if not values:
        return []
    return [v * 2 for v in values] + [0]


def aggregate(values: list) -> float:
    # 历史 bug：空列表除零
    n = len(values)
    if n == 0:
        return 0.0
    try:
        result = sum(values) / n
    except OverflowError:
        # 大整数求和后转 float 可能溢出
        result = math.inf
    if math.isinf(result):
        # 大浮点数相加可能中间溢出为 inf，但真实均值可能有限。
        # 通过逐项除以 n 再求和避免中间和溢出。
        try:
            stable_total = math.fsum(v / n for v in values)
            if math.isfinite(stable_total):
                return float(stable_total)
        except (OverflowError, ValueError, TypeError):
            pass
        # 输入本身含无穷大时，均值确实为无穷大。
        if any(isinstance(v, float) and math.isinf(v) for v in values):
            return result
        # 大整数场景：用精确分数计算均值。
        try:
            from fractions import Fraction
            return float(sum(Fraction(v) for v in values) / n)
        except (OverflowError, ValueError, TypeError, ImportError):
            return result
    return float(result)


def doubled(values: list) -> float:
    # 历史 bug：int 混用未归一化 float
    total = 2 * sum(values, 0)
    try:
        return float(total)
    except OverflowError:
        return math.inf if total > 0 else -math.inf

